/bin/bash -lc "python - <<'PY'
import urllib.parse, urllib.request, json
queries=[
 '\"unperturbed\" \"primary tissues\" \"cell lines\" chromatin accessibility',
 '\"unperturbed human\" ATAC-seq depleted',
 '\"large public\" \"cell lines\" \"chromatin accessibility\"',
 '\"depleted\" \"unperturbed\" ATAC-seq human'
]
for q in queries:
 url='https://www.ebi.ac.uk/europepmc/webservices/rest/search?format=json&query='+urllib.parse.quote(q)
 try:
  d=json.load(urllib.request.urlopen(url,timeout=30))
  print('\\nQUERY',q,'hits',d.get('hitCount'))
  for x in d.get('resultList',{}).get('result',[])[:10]: print(x.get('title'),x.get('pmcid'),x.get('pubYear'))
 except Exception as e: print(e)
PY"

